
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_wpbeh_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_wpbeh", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.292405100372975e+00, -4.211111960972908e+00, -4.097371870439805e+00, -3.940173053024237e+00, -3.726724023365291e+00, -3.444205956162445e+00, -3.083690944663680e+00, -2.646351987052546e+00, -2.147540304439108e+00, -1.612615147739802e+00, -1.090305404399731e+00, -7.078101534603521e-01, -6.005586877571500e-01, -5.012086258357505e-01, -3.718803245355399e-01, -2.422080451016200e-01, -1.330951825332417e-01, -5.013250583623208e-02, -1.082147705770433e-02, -1.216216048140391e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


